(()=>{let filter='all';const group=status=>status==='completed'?'completed':['cancelled','declined'].includes(status)?'cancelled':'progress';const label={all:'All tickets',progress:'In progress',completed:'Completed',cancelled:'Cancelled'};function draw(){if(!localToken||!localUser||role!=='customer'||view!=='home'||!data)return;const card=[...document.querySelectorAll('.card')].find(x=>x.querySelector('h3')?.textContent.includes('Your service requests'));if(!card)return;const bookings=data.bookings||[],shown=filter==='all'?bookings:bookings.filter(x=>group(x.status)===filter),counts={all:bookings.length,progress:bookings.filter(x=>group(x.status)==='progress').length,completed:bookings.filter(x=>group(x.status)==='completed').length,cancelled:bookings.filter(x=>group(x.status)==='cancelled').length};card.classList.add('tickets-card');card.innerHTML=`<div class="row"><div><div class="eyebrow">MY TICKETS</div><h3>Service requests</h3></div><span class="pill">${counts.all}</span></div><div class="ticket-filters">${Object.entries(label).map(([id,name])=>`<button type="button" class="${filter===id?'active':''}" data-ticket-filter="${id}">${name}<b>${counts[id]}</b></button>`).join('')}</div><div class="ticket-list">${shown.length?shown.map(ticket=>`<button type="button" class="ticket-row" data-ticket-open="${ticket.id}"><span><strong>${esc(svc(ticket.service).en)}</strong><small>${esc(ticket.village)} · ${esc(ticket.id)}</small></span><span class="ticket-status ${group(ticket.status)}">${esc(status(ticket))}</span></button>`).join(''):`<p class="muted">No ${label[filter].toLocaleLowerCase()} yet.</p>`}</div>`;card.querySelectorAll('[data-ticket-filter]').forEach(button=>button.onclick=()=>{filter=button.dataset.ticketFilter;draw();});card.querySelectorAll('[data-ticket-open]').forEach(button=>button.onclick=()=>{selected=button.dataset.ticketOpen;view='booking';render();});}const baseRender=render;render=function(){baseRender();draw();};})();
